const builtInCategoryNames=['Alimentação','Transporte','Moradia','Saúde','Educação','Lazer','Assinaturas','Casamento','Viagem','Outros'];
const categoryKey=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim().toLowerCase();
const validCategoryName=value=>typeof value==='string'&&value.normalize('NFC').replace(/\s+/g,' ').trim().length>=2&&value.normalize('NFC').replace(/\s+/g,' ').trim().length<=60&&/^[\p{L}\p{N} &'’().\/-]+$/u.test(value);
let categoryNames=[...builtInCategoryNames],categoryCatalogAvailable=false;
function initCategoryCatalog(context){
 let value=context?.categoryContext;
 if(!value){try{value=$('Unir categorias da carteira').first().json.categoryContext;}catch{}}
 categoryCatalogAvailable=value?.available===true;
 const supplied=categoryCatalogAvailable&&Array.isArray(value.categories)?value.categories:[];
 const names=[...supplied.map(c=>typeof c==='string'?c:c?.name).filter(validCategoryName),...builtInCategoryNames];
 categoryNames=names.filter((c,i,a)=>a.findIndex(n=>categoryKey(n)===categoryKey(c))===i);
 return {available:categoryCatalogAvailable,categories:categoryNames.map(name=>({name}))};
}
const resolveCategory=value=>validCategoryName(value)?categoryNames.find(name=>categoryKey(name)===categoryKey(value))||null:null;

const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const plain = value => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const br = value => Number(value).toLocaleString('pt-BR', {style:'currency',currency:'BRL'});
const cents = value => Math.round(Number(value) * 100);
const total = rows => rows.reduce((sum, tx) => sum + cents(tx.amount), 0) / 100;
const paymentFrom = text => {
  const t = plain(text);
  if (/\bpix\b/.test(t)) return {method:'pix'};
  if (/\bdinheiro\b/.test(t)) return {method:'dinheiro'};
  if (/\bdebito\b/.test(t)) return {method:'debito'};
  if (/\b(?:cartao|credito)\b/.test(t)) return {method:'cartao',installments:1,cash_amount:'0.00'};
  return null;
};
const inferCategoryFrom = text => {
  const t = plain(text);
  return [
    [/\bviage(?:m|ns)\b/, 'Viagem'], [/\bcasamento\b/, 'Casamento'],
    [/mercado|supermercado|padaria|restaurante|lanche|comida|ifood|alimenta/, 'Alimentação'],
    [/uber|\b99\b|taxi|combust|gasolina|transporte/, 'Transporte'],
    [/aluguel|condom|\bluz\b|energia|\bagua\b|internet|moradia/, 'Moradia'],
    [/farmacia|medico|consulta|saude/, 'Saúde'], [/curso|escola|faculdade|livro|educacao/, 'Educação'],
    [/cinema|\bbar\b|show|lazer/, 'Lazer'], [/netflix|spotify|assinatura/, 'Assinaturas'],
    [/\boutros\b/, 'Outros'],
  ].find(([pattern]) => pattern.test(t))?.[1] ?? null;
};
const categoryFrom = value => resolveCategory(String(value??'').trim()) || inferCategoryFrom(value);
const moneyIn = text => {
  const result = [];
  const pattern = /(?<![\p{L}\d.,/])(?:R\$\s*)?(\d{1,3}(?:\.\d{3})+(?:,\d{1,2})?|\d+(?:[.,]\d{1,2})?)(?!\d|[.,]\d|\/\d)/giu;
  for (const m of String(text).matchAll(pattern)) {
    const tail = text.slice(m.index + m[0].length);
    if (/^\s*(?:x\b|vezes\b|parcelas?\b|compras?\b|itens?\b|dias?\b|meses\b|anos?\b)/i.test(tail)) continue;
    const prefix = text.slice(Math.max(0,m.index - 45),m.index);
    const labelled = /(?:valor(?:\s+(?:pago|total|da compra))?|total(?:\s+(?:pago|da compra|do pedido))?)\s*[:\-]?\s*$/i.test(prefix);
    const raw = m[1];
    const amount = Number(raw.includes(',') || /^\d{1,3}(?:\.\d{3})+$/.test(raw) ? raw.replace(/\./g,'').replace(',','.') : raw);
    if (Number.isFinite(amount) && amount > 0 && amount <= 100000000) result.push({amount,raw,match:m[0],index:m.index,labelled,currency:/r\$/i.test(m[0]),decimal:/[.,]/.test(raw)});
  }
  const priority = result.some(x=>x.labelled) ? result.filter(x=>x.labelled) : result.some(x=>x.currency) ? result.filter(x=>x.currency) : result.some(x=>x.decimal) ? result.filter(x=>x.decimal) : result;
  return priority.filter((x,i,a)=>a.findIndex(y=>cents(y.amount)===cents(x.amount))===i);
};
const pendingRows = p => Array.isArray(p?.transactions) ? p.transactions : p?.tx ? [p.tx] : [];
const withMetadata = (tx, category, payment) => ({...tx,category:category || tx.category || 'Outros',payment_details:payment || tx.payment_details || {}});

let x = $input.first().json;
let ai = {};
if (x.output !== undefined || x.error) {
  const raw = x.output;
  try { ai = typeof raw === 'string' ? JSON.parse(raw.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')) : raw ?? {}; } catch {}
  x = $('Preparar intenção financeira').first().json;
}
if (x.route === 'reply' || x.route === 'transaction') return [{json:x}];
x={...x,categoryContext:initCategoryCatalog(x)};
// A recurrence request is a scheduling question, never proof of a paid expense.
// This narrow fallback also runs when the intention model is unavailable.
{
 const recurrenceText=String(x.text??'');
 const recurrencePlain=plain(recurrenceText);
 const withoutCategoryLabel=recurrencePlain.replace(/\bcategoria\s+(?:(?:chamada|nova|de|como)\s+)?recorrencia\b/g,'categoria definida');
 const recurrenceLabelOnly=withoutCategoryLabel!==recurrencePlain&&!/\b(?:recorrente|recorrencia|todo mes|todos os meses|mensalmente|toda semana|semanalmente)\b/.test(withoutCategoryLabel);
 const asksToAdd=/\b(?:inclu\w*|adicion\w*|cadastr\w*|crie|criar)\b/.test(recurrencePlain);
 const hasRecurrence=/\b(?:recorrente|recorrencia|todo mes|todos os meses|mensalmente|toda semana|semanalmente)\b/.test(recurrencePlain);
 const isExpense=/\b(?:despesa|gasto|conta|fatura|assinatura)\b/.test(recurrencePlain);
 const denies=/\b(?:nao|nunca|cancele|cancelar|exclua|excluir|apague|apagar)\b/.test(recurrencePlain);
 const values=moneyIn(recurrenceText);
 if(x.mediaKind==='text'&&asksToAdd&&hasRecurrence&&isExpense&&!denies&&!recurrenceLabelOnly&&values.length===1){
  const value=values[0];
  const withoutAmount=recurrenceText.slice(0,value.index)+' '+recurrenceText.slice(value.index+value.match.length);
  const description=clean(withoutAmount
   .replace(/\b(?:inclu\w*|adicion\w*|cadastr\w*|crie|criar|uma|um|despesa|gasto|conta|fatura|assinatura|recorrente|recorrência|recorrencia|todo\s+m[eê]s|todos\s+os\s+meses|mensalmente|toda\s+semana|semanalmente)\b/giu,' ')
   .replace(/^[\s,;:.-]+|[\s,;:.-]+$/g,'').replace(/\s*[,;:]\s*/g,' '));
  if(description&&description.length<=180){
   const recurrenceState=$getWorkflowStaticData('global');
   recurrenceState.alertConversations??={};
   recurrenceState.alertConversations[x.chatId+':'+x.senderId]={at:Date.now(),values:{description,amount:value.amount,kind:'payment'},single_occurrence_offer:true};
   return [{json:{...x,route:'reply',financialStatus:'alerta_esclarecer',replyText:'Entendi uma despesa recorrente de '+br(value.amount)+' — '+description+'. Ainda não crio lançamentos recorrentes automaticamente por aqui. Posso preparar um lembrete apenas para o próximo vencimento. Qual é a data? Nenhuma despesa foi registrada.'}}];
  }
 }
}

if(x.mediaKind==='text'&&x.intentInput&&(!ai||typeof ai.intent!=='string'))return [{json:{...x,route:'reply',financialStatus:'conversa',replyText:'Não consegui entender seu pedido com segurança agora. Pode me contar de outro jeito?'}}];
// The native AI interprets language; this boundary validates identities, fields and confirmations.
const semanticState=$getWorkflowStaticData('global');semanticState.management??={};
const semanticKey=x.chatId+':'+x.senderId;
let session=semanticState.management[semanticKey];
if(session&&(session.userId!==x.user?.id||Date.now()-session.at>15*60*1000)){delete semanticState.management[semanticKey];session=null;}
const human=(replyText,financialStatus='gestao_selecao')=>[{json:{...x,route:'reply',replyText,financialStatus}}];
const catalog=Array.isArray(x.ledgerContext)?x.ledgerContext.filter(r=>r.user_id===x.user?.id&&!r.deleted_at):[];
const allowed=[...catalog,...(session?.rows||[])].filter(r=>r.user_id===x.user?.id&&!r.deleted_at);
const semantics=ai.management&&typeof ai.management==='object'?ai.management:{};
const act=semantics.action||'none';
const currentText=String(x.text||'');
const negativeOrQuestion=/\?/.test(currentText)||/\b(?:nao|nunca|talvez|ainda nao|se der)\b/.test(plain(currentText));
const brief=r=>`${br(r.amount)} — ${clean(r.description)} (${r.transaction_date})`;

// Embedded in Classificar comando after the current input and trusted context exist.
const payerUUID = value => typeof value==='string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
const payerContext = x.payerContext?.available===true ? x.payerContext : null;
const payerRoster = payerContext && Array.isArray(payerContext.participants) ? payerContext.participants.filter(p=>payerUUID(p?.id)&&typeof p.active==='boolean') : [];
const payerPeople = payerRoster.filter(p=>p.active===true);
const payerName = value => clean(value).replace(/[\p{C}@_*~`<>\[\]]/gu,' ').replace(/\s+/g,' ').trim().slice(0,60) || 'Pessoa cadastrada';
const payerPerson = id => {const matches=payerPeople.filter(p=>p.id.toLowerCase()===String(id).toLowerCase());return matches.length===1?matches[0]:null;};
const payerProposal = draft => {
  if(draft.payer_needs_clarification===true)return null;
  const input=draft.payer??{kind:'unknown',participant_ids:[]};
  if(!input||typeof input!=='object'||Array.isArray(input)||!['unknown','participant','joint'].includes(input.kind))return null;
  const ids=input.participant_ids??[];
  if(!Array.isArray(ids)||ids.some(id=>!payerUUID(id)))return null;
  const normalized=ids.map(id=>id.toLowerCase());
  if(new Set(normalized).size!==normalized.length)return null;
  if((input.kind==='unknown'&&ids.length)||(input.kind==='participant'&&ids.length!==1)||(input.kind==='joint'&&ids.length<2))return null;
  if(input.kind!=='unknown'&&(!payerContext||normalized.some(id=>!payerPerson(id))))return null;
  return {kind:input.kind,participant_ids:[...normalized].sort()};
};
const payerText = tx => {
  if(tx.transaction_type!=='despesa')return '';
  if(tx.payerFrozenVersion!==1)return ' — Pagador: não identificado';
  return ' — Pagador: '+(tx.payer.kind==='unknown'?'não identificado':tx.payerLabel);
};

const personQuery=plain(x.text||'');
// Only verified roster names bind a query to a participant. Legacy aliases may
// enter the clarification guard, but never imply a binding to another name.
const payerQueryWords=' '+personQuery.replace(/[^\p{L}\p{N}\s]/gu,' ').replace(/\s+/g,' ').trim()+' ';
const payerQueryPeople=payerRoster.filter(p=>{
 const name=plain(p.display_name),first=name.split(' ')[0];
 return [name,first].filter(s=>s.length>=2).some(s=>payerQueryWords.includes(' '+s+' '));
});

if(/\b(?:despesas?|gastos?|lancamentos?)\b/.test(personQuery)&&(/\b(?:ionara|narinha|guiga|nara|nicolas|nic)\b/.test(personQuery)||payerQueryPeople.length>0)&&(/\?/.test(x.text||'')||/\b(?:quais|cad[eê]|mostr\w*|ver|consult\w*|e os|e as)\b/.test(personQuery))&&!/\b(?:exclu\w*|apag\w*|edit\w*|alter\w*)\b/.test(personQuery)){
const recentExpenses=catalog.filter(r=>r.transaction_type==='despesa').slice(0,50);
if(!payerContext){
 return human('A identificação de pagadores não está disponível agora. Não vou atribuir gastos a alguém sem confirmar essa informação. A carteira continua compartilhada.','gestao_consulta_compartilhada');
}
if(!payerRoster.length)return human('Não há participantes cadastrados disponíveis para identificar pagadores agora. A carteira continua compartilhada.','gestao_consulta_compartilhada');
const mentions=payerQueryPeople;
if(mentions.length!==1)return human('De quem você quer consultar os pagamentos? Posso conferir por '+payerRoster.map(p=>payerName(p.display_name)).join(' ou ')+'.','gestao_consulta_compartilhada');
const person=mentions[0],attrs=Array.isArray(payerContext.attributions)?payerContext.attributions:[];
const map=new Map();
for(const a of attrs){
 if(a.finance_user_id!==x.user?.id||!payerUUID(a.transaction_id)||!['unknown','participant','joint'].includes(a.kind)||!Array.isArray(a.participant_ids))continue;
 const key=a.transaction_id.toLowerCase();
 if(map.has(key)){map.set(key,null);continue;}
 map.set(key,a);
}
const individual=[],joint=[];let unknown=0;
for(const row of recentExpenses){
 const a=map.get(row.id.toLowerCase());
 if(!a||a.kind==='unknown'){unknown++;continue;}
 const ids=a.participant_ids.map(String).map(s=>s.toLowerCase());
 if(a.kind==='participant'&&ids.length===1&&ids[0]===person.id.toLowerCase())individual.push(row);
 else if(a.kind==='joint'&&ids.includes(person.id.toLowerCase()))joint.push(row);
}
const limit='Consulta dos até 50 lançamentos recentes disponíveis; não é um total mensal.';
const list=rows=>rows.slice(0,10).map(r=>'• '+brief(r)).join('\n');
const who=payerName(person.display_name);
return human('Pagamentos individuais identificados de '+who+':'+(individual.length?'\n'+list(individual):' nenhum nesse recorte.')+(joint.length?'\n\nPagamentos conjuntos com '+who+' (sem divisão presumida):\n'+list(joint):'')+'\n\n'+unknown+' despesa(s) desse recorte continuam sem pagador identificado. '+limit,'gestao_consulta_compartilhada');
}

const activeProposal=session?.proposal?.semantic===true?session.proposal:null;


function categoryPendingReply(context,name,values,state){
 const proposal=state.pending?.[context.chatId];
 const rows=Array.isArray(proposal?.transactions)?proposal.transactions:proposal?.tx?[proposal.tx]:[];
 const key=context.chatId+':'+context.senderId;
 const reply=text=>[{json:{...context,route:'reply',financialStatus:'alerta_categoria',replyText:text}}];
 if(!proposal||Date.now()-Number(proposal.at)>30*60*1000||!rows.length)return reply('Não há uma proposta de lançamento pendente para receber essa categoria. Qual lançamento você quer ajustar?');
 if(Object.prototype.hasOwnProperty.call(values,'expectedProposalKey')&&(proposal.sourceMessageId??null)!==values.expectedProposalKey)return reply('A categoria foi criada, mas a proposta de lançamento mudou durante o pedido. Em qual proposta você quer aplicá-la?');
 let indexes;
 if(rows.length===1||values.apply_all===true)indexes=rows.map((_,i)=>i);
 else if(Array.isArray(values.item_numbers)&&values.item_numbers.length&&values.item_numbers.every(i=>Number.isInteger(i)&&i>=1&&i<=rows.length)&&new Set(values.item_numbers).size===values.item_numbers.length)indexes=values.item_numbers.map(i=>i-1);
 else{
  state.categoryConversations[key]={at:Date.now(),userId:context.user.id,name,target:'pending',phase:'choose_items',proposalKey:proposal.sourceMessageId};
  return reply('A categoria '+name+' está disponível. Quer aplicá-la em todos os '+rows.length+' itens da proposta ou em quais itens?');
 }
 const previous=state.categoryConversations?.[key];
 if(previous?.phase==='choose_items'&&previous.proposalKey!==proposal.sourceMessageId)return reply('A proposta de lançamento mudou. Em quais itens da proposta atual você quer usar a categoria '+name+'?');
 const transactions=rows.map((tx,i)=>indexes.includes(i)?{...tx,category:name}:tx);
 proposal.transactions=transactions;if(proposal.tx)proposal.tx=transactions[0];proposal.at=Date.now();
 state.categoryConversations[key]={at:Date.now(),userId:context.user.id,name,target:'pending',phase:'applied',proposalKey:proposal.sourceMessageId};
 const money=value=>Number(value).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 const lines=transactions.map((tx,i)=>(i+1)+'. '+(tx.transaction_type==='receita'?'Entrada: ':'Saída: ')+money(tx.amount)+' — '+tx.description+' ('+tx.category+')'+(tx.transaction_type==='despesa'&&tx.payerLabel?' — Pagador: '+tx.payerLabel:''));
 return [{json:{...context,route:'reply',financialStatus:'aguardando_confirmacao',verifiedCategoryProposal:true,replyText:'Categoria ajustada somente na proposta:\n'+lines.join('\n')+'\nEstá certo para registrar esses itens? Nenhum lançamento foi gravado ainda.'}}];
}

function categoryExistingReply(context,name,target,state){
 const key=context.chatId+':'+context.senderId;
 const reply=(replyText,financialStatus='gestao_edicao')=>[{json:{...context,route:'reply',financialStatus,replyText}}];
 const catalog=Array.isArray(context.ledgerContext)?context.ledgerContext.filter(r=>r.user_id===context.user?.id&&!r.deleted_at):[];
 let session=state.management?.[key];
 if(session&&(session.userId!==context.user.id||Date.now()-Number(session.at)>15*60*1000))session=null;
 let selected=target==='selected'?session?.selected:null;
 if(target==='recent'){
  const recent=state.recent?.[context.chatId],rows=Array.isArray(recent?.transactions)?recent.transactions:[];
  if(recent&&Date.now()-Number(recent.at)<=30*60*1000&&rows.length===1)selected=catalog.find(r=>r.id===rows[0].id);
 }
 const allowed=[...catalog,...(session?.rows||[])].filter(r=>r.user_id===context.user.id&&!r.deleted_at);
 if(!selected||selected.user_id!==context.user.id||!allowed.some(r=>r.id===selected.id))return reply('Qual lançamento você quer colocar em '+name+'? Preciso identificar um único lançamento antes de propor a alteração.');
 session??={userId:context.user.id,at:Date.now(),rows:catalog,page:0};
 session.selected=selected;session.at=Date.now();session.mode='edit';delete session.clarification;
 session.proposal={kind:'update',record:selected,changes:{category:name},semantic:true,token:context.messageId+':update:'+selected.id};
 state.management??={};state.management[key]=session;
 const money=Number(selected.amount).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
 return reply('Em '+money+' — '+selected.description+' ('+selected.transaction_date+'), a categoria vai ficar '+name+'. Está certo assim? Nenhum lançamento foi alterado ainda.','gestao_confirmacao');
}

// Only structured semantic actions can create a category or select an editing target.
semanticState.categoryConversations??={};
let categoryDraft=semanticState.categoryConversations[semanticKey];
if(categoryDraft&&(categoryDraft.userId!==x.user?.id||Date.now()-Number(categoryDraft.at)>15*60*1000)){delete semanticState.categoryConversations[semanticKey];categoryDraft=null;}
const categoryIntent=ai.category_action||(ai.category&&typeof ai.category==='object'?ai.category:{});
const categoryAction=categoryIntent.action||'none';
if(!['none','create','list','apply','clarify'].includes(categoryAction))return human('Não consegui entender a ação de categoria com segurança. Você quer criar uma categoria ou usá-la em um lançamento?','alerta_categoria');
if(categoryAction!=='none'){
 if(!categoryCatalogAvailable)return human('Não consegui consultar as categorias da carteira agora. Não criei nem alterei categoria ou lançamento.','alerta_categoria');
 if(categoryAction==='list')return human('Categorias disponíveis:\n'+categoryNames.map(name=>'• '+name).join('\n'),'alerta_categoria');
 const requestedName=typeof categoryIntent.name==='string'&&categoryIntent.name.trim()?categoryIntent.name:categoryDraft?.name;
 if(!validCategoryName(requestedName))return human('Qual nome você quer dar à categoria? Use de 2 a 60 caracteres, com letras, números ou pontuação simples.','alerta_categoria');
 const name=resolveCategory(requestedName)||requestedName.normalize('NFC').replace(/\s+/g,' ').trim();
 const target=['pending','selected','recent','none'].includes(categoryIntent.target)?categoryIntent.target:categoryDraft?.target||'none';
 if(categoryAction==='clarify'){semanticState.categoryConversations[semanticKey]={at:Date.now(),userId:x.user.id,name,target,phase:'clarify'};return human('Você quer criar a categoria '+name+' ou aplicar essa categoria a qual lançamento?','alerta_categoria');}
 if(categoryAction==='create'){
  const prior=categoryDraft&&categoryKey(categoryDraft.name)===categoryKey(name)?categoryDraft:{};
  semanticState.categoryConversations[semanticKey]={...prior,at:Date.now(),userId:x.user.id,name,target,phase:'creating',apply_all:categoryIntent.apply_all===true,item_numbers:categoryIntent.item_numbers};
  return [{json:{...x,route:'category_execute',categoryOperation:'create',categoryValues:{name},categoryTarget:target,categoryApplyAll:categoryIntent.apply_all===true,categoryItemNumbers:categoryIntent.item_numbers,categoryExpectedProposalKey:target==='pending'?(semanticState.pending?.[x.chatId]?.sourceMessageId??null):null}}];
 }
 if(!resolveCategory(name)){
  semanticState.categoryConversations[semanticKey]={at:Date.now(),userId:x.user.id,name,target,phase:'ask_create'};
  return human('A categoria '+name+' ainda não está cadastrada. Quer criar essa categoria? Nenhum lançamento foi alterado.','alerta_categoria');
 }
 if(target==='pending')return categoryPendingReply(x,resolveCategory(name),categoryIntent,semanticState);
 if(target==='selected'||target==='recent')return categoryExistingReply(x,resolveCategory(name),target,semanticState);
 return human('A categoria '+name+' está disponível. Em qual lançamento você quer usá-la?','alerta_categoria');
}

const financialQuery=ai.financial_query||{};
if(financialQuery.action&&financialQuery.action!=='none'){
 if(payerQueryPeople.length||/\b(?:ionara|narinha|guiga|nara|nicolas|nic)\b/.test(personQuery))return human('Essa consulta envolve uma pessoa. A consulta livre não transforma nome de pessoa em descrição de gasto nem presume quem pagou. Posso conferir pagamentos identificados no recorte de até 50 lançamentos recentes; qual pessoa e quais pagamentos você quer consultar?','gestao_consulta_compartilhada');
 const permitted=['action','date_from','date_to','type','category','search','limit','inherit','subset_only'];
 if(!['list','total','breakdown'].includes(financialQuery.action)||Object.keys(financialQuery).some(k=>!permitted.includes(k)))return human('Não consegui validar os filtros dessa consulta. Qual período e categoria você quer consultar?','gestao_consulta_livre');
 if(financialQuery.subset_only===true)return human('O limite de exibição escolhe quantos itens mostrar; os totais dessa consulta incluem todos os lançamentos que correspondem aos filtros. Para somar só determinados itens, preciso identificar esse recorte por período, categoria ou descrição. Qual recorte você quer usar?','gestao_consulta_livre');
 const prior=semanticState.queryConversations?.[semanticKey];
 const inherited=financialQuery.inherit===true&&prior?.userId===x.user.id&&Date.now()-Number(prior.at)<=15*60*1000?prior.filters:{};
 const values={...inherited,...Object.fromEntries(Object.entries(financialQuery).filter(([k])=>!['inherit','subset_only'].includes(k)))};
